/**
 * Loads the prebuilt single-file SPICE client bundle.
 *
 * The bundle (public/spice-html5/spice-bundle.js) concatenates the vendored
 * spice-html5 sources in dependency order - generated by
 * scripts/build-spice-bundle.mjs and regenerated by the pre(build|dev) npm
 * hooks. Loading one file replaces ~29 sequential <script> round-trips and the
 * old fixed 200ms settle delay: the library installs its globals
 * (window.SpiceMainConn, etc.) synchronously, so the script's `load` event is
 * the precise ready signal.
 */

const BUNDLE_SRC = "/spice-html5/spice-bundle.js";
const CSS_HREF = "/spice-html5/spice.css";

let loadingPromise: Promise<void> | null = null;
let loaded = false;

export function isSpiceLoaded(): boolean {
  return loaded;
}

export function loadSpiceScripts(): Promise<void> {
  if (loaded) return Promise.resolve();
  if (loadingPromise) return loadingPromise;

  loadingPromise = new Promise<void>((resolve, reject) => {
    const ensureCss = () => {
      if (!document.querySelector(`link[href="${CSS_HREF}"]`)) {
        const link = document.createElement("link");
        link.rel = "stylesheet";
        link.href = CSS_HREF;
        document.head.appendChild(link);
      }
    };

    const finish = () => {
      if (typeof (window as any).SpiceMainConn === "undefined") {
        reject(new Error("SPICE bundle loaded but SpiceMainConn is unavailable"));
        return;
      }
      loaded = true;
      resolve();
    };

    // Already present (e.g. a second console mounted on the same page).
    if ((window as any).SpiceMainConn) {
      ensureCss();
      finish();
      return;
    }

    ensureCss();

    const existing = document.querySelector(
      `script[src="${BUNDLE_SRC}"]`,
    ) as HTMLScriptElement | null;

    if (existing) {
      existing.addEventListener("load", finish, { once: true });
      existing.addEventListener(
        "error",
        () => reject(new Error("Failed to load SPICE bundle")),
        { once: true },
      );
      return;
    }

    const el = document.createElement("script");
    el.src = BUNDLE_SRC;
    el.async = false;
    el.onload = finish;
    el.onerror = () => reject(new Error("Failed to load SPICE bundle"));
    document.head.appendChild(el);
  });

  return loadingPromise;
}
